const cards = [
  {
    image: "./images/the-scream.jpg",
    alt: "Фигура на мосту в искажённом пейзаже, выражающая отчаяние и тревогу",
    title: "The Scream",
  },
  {
    image: "./images/the-persistence-of-memory.jpg",
    alt: "Пейзаж с расплавленными часами, символизирующими иллюзорность времени",
    title: "The Persistence of Memory",
  },
  {
    image: "./images/girl-with-a-pearl-earring.jpg",
    alt: "Портрет девушки в тюрбане, обернувшейся через плечо с загадочным взглядом",
    title: "Girl with a Pearl Earring",
  },
  {
    image: "./images/penitent-mary-magdalene.jpg",
    alt: "Женская фигура с поднятым взглядом и руками на груди, в позе раскаяния и молитвы",
    title: "Penitent Mary Magdalene",
  },
];

const cardsContainer = document.querySelector(".cards");
const popup = document.querySelector(".popup");
const popupImage = popup.querySelector(".popup__image");
const closePopupButton = popup.querySelector(".popup__close-button");

function createCard(item) {
  const template = document.getElementById("card-template");
  const clone = template.content.querySelector(".cards__item").cloneNode(true);
  const card = clone.querySelector(".card__image");
  const cardImage = clone.querySelector(".card__image");
  const cardDeleteButton = clone.querySelector(".card__delete-button");
  const cardTitle = clone.querySelector(".card__title");

  cardImage.src = item.image;
  cardImage.alt = item.alt;
  cardTitle.textContent = item.title;

  card.addEventListener("click", () => {
    popupImage.src = cardImage.src;
    popupImage.alt = cardImage.alt;
    popup.classList.add("popup_is-opened");
  });

  cardDeleteButton.addEventListener("click", (event) => {
    event.stopPropagation();

    const cardContainer = cardDeleteButton.closest(".cards__item");
    if (cardContainer) cardContainer.remove();
  });

  return clone;
}

cards.forEach((card) => {
  const newCard = createCard(card);
  cardsContainer.append(newCard);
});

closePopupButton.addEventListener("click", () => {
  popup.classList.remove("popup_is-opened");
  popupImage.src = "";
  popupImage.alt = "";
});
